import React, { useEffect, useState } from 'react';
// import { getBoxOffice } from '../api/movieApi'; // 실제 API 호출 함수
import MovieCard from '../components/MovieCard';

// 임시 데이터를 이미지에 맞게 확장
const MOCK_MOVIES = [
  {
    id: 1,
    title: '영화 1',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
  },
  {
    id: 2,
    title: '영화 2',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    details: {
      '영화 제목': '영화 2',
      '개봉일': '2025.01.01',
      '감독': '홍길동',
      '배우': '김배우, 이배우',
      '장르': '드라마',
      '관람 등급': '15세 이상 관람가',
    },
  },
  {
    id: 3,
    title: '영화 3',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
  },
  {
    id: 4,
    title: '영화 4',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
  },
  {
    id: 5,
    title: '영화 5',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
  },
  {
    id: 6,
    title: '영화 6',
    poster_path: 'https://via.placeholder.com/120x170/e8e8e8/a8a8a8?text=Image',
    description: 'Body text for whatever you\'d like to say. Add main takeaway points, quotes, anecdotes, or even a very very short story.',
  },
];

function HomePage() {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMovies = async () => {
      try {
        setLoading(true);
        // TODO: 실제 API 연동 시 아래 주석 해제
        // const response = await getBoxOffice();
        // setMovies(response.results);
        
        // 임시 데이터 사용
        setTimeout(() => {
          setMovies(MOCK_MOVIES);
          setLoading(false);
        }, 500);

      } catch (error) {
        console.error("영화 정보를 가져오는 데 실패했습니다.", error);
        setLoading(false);
      }
    };

    fetchMovies();
  }, []);

  if (loading) return <div>로딩 중...</div>;

  return (
    // 전체 레이아웃을 감싸는 div 추가
    <div style={styles.container}>
      <h1 style={styles.title}>박스오피스</h1>
      {/* 영화 목록을 Grid로 변경 */}
      <div style={styles.movieGrid}>
        {movies.map(movie => (
          <MovieCard key={movie.id} movie={movie} />
        ))}
      </div>
    </div>
  );
}

// 스타일 객체를 만들어 가독성 향상
const styles = {
  container: {
    width: '100%',
    maxWidth: '1200px', // 최대 너비 설정
    margin: '0 auto', // 가운데 정렬
    padding: '2rem',
    backgroundColor: '#f0f2f5', // 이미지와 유사한 배경색
    boxSizing: 'border-box',
  },
  title: {
    fontSize: '2.5rem',
    textAlign: 'center',
    marginBottom: '3rem',
    fontWeight: 'bold',
  },
  movieGrid: {
    display: 'grid',
    // 3개의 열을 만들고, 각 열은 동일한 비율(1fr)을 가짐
    gridTemplateColumns: 'repeat(3, 1fr)', 
    gap: '2rem', // 카드 사이의 간격
  },
};

export default HomePage;
